def logger(func):
    def wrapper(*args):
        print(f'Calling {func.__name__}')
        return func(*args)
    return wrapper

@logger
def greet(name):
    return f'Hi {name}'

print(greet('Alice'))

def square_gen(n):
    for i in range(n):
        yield i ** 2

for sq in square_gen(5):
    print(sq)
